// Board-root and lead-channel-name resolution for the Atlas mod data plane.
// Pure logic: no $, no Node APIs; all IO goes through the injected FsLike
// (mods have no node:path, so join/parent are computed inline). Plan: §2.
import type { FsLike } from '../contract';

/**
 * Root of the Atlas data tree: ATLAS_PROJECT_ROOT when set and holding `.atlas`,
 * else the nearest ancestor of cwd that holds `.atlas` (the boardRoot rule in
 * omp/channel-view.ts:74-80), probing at most 12 levels. null when nothing does.
 */
export async function boardRoot(
	fs: FsLike,
	cwd: string,
	env: { ATLAS_PROJECT_ROOT?: string },
): Promise<string | null> {
	const override = env?.ATLAS_PROJECT_ROOT ?? '';
	if (override && (await fs.exists(override.endsWith('/') ? override + '.atlas' : override + '/.atlas'))) {
		return override;
	}
	let dir = cwd;
	for (let i = 0; i < 12; i++) {
		if (await fs.exists(dir.endsWith('/') ? dir + '.atlas' : dir + '/.atlas')) return dir;
		// Parent walk: strip trailing slashes, cut before the last '/'; the root is its own parent.
		const stripped = dir.replace(/\/+$/, '');
		const cut = stripped.lastIndexOf('/');
		const parent = cut <= 0 ? '/' : stripped.slice(0, cut);
		if (parent === dir) return null;
		dir = parent;
	}
	return null;
}

/**
 * Candidate channel names for the lead's IRC channel, in resolution order:
 * `lead-<first 6 of session id>` (the lead_name rule in scripts/atlas_todo.py:1359,
 * pinned by hooks/session_boot.py:815-837), then `<folder>@<branch>` fallback
 * when the lead channel is not in channels.json.
 */
export function leadChannelName(sessionId: string, folder: string, branch: string): string[] {
	return [`lead-${sessionId.slice(0, 6)}`, `${folder}@${branch}`];
}

files.mod/data/todos.ts:
// TODO board reader for the Atlas mod. Pure over FsLike (see ../contract);
// register.ts adapts $.fs onto it. Source: <root>/.atlas/.run/todos.json
// {version, items[]}, replaced atomically by scripts/atlas_todo.py, so the
// poll key is stat mtimeMs (plan §2, docs/plans/2026-10-09-atlas-mod.md).
import type { AtlasSnapshot, Contract, FsLike, PhaseCount, PhaseId, TodoItem } from '../contract';
import type { TodoGroup } from '../orchestra-types';

/** Phase -> department label (the single copy; pane/board.tsx imports it). */
export const DEPT: Record<string, string> = {
  research: 'ARCHIVE',
  theory: 'OBSERVATORY',
  test: 'TEST LAB',
  validate: 'GATE',
  implement: 'FORGE',
  verify: 'TRIBUNAL',
  done: 'HARBOUR',
};

/** Reusable read result: items already filtered + phase-stamped for one (root, session, members) caller. */
export interface TodosCache { mtimeMs: number; items: TodoItem[] }

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function prefixRegex(contract: Contract): RegExp | null {
  const i = contract.itemPhasePrefix.indexOf('<phase>');
  if (i < 0) return null;
  return new RegExp(
    '^' + escapeRe(contract.itemPhasePrefix.slice(0, i)) +
    '([a-z]+)' +
    escapeRe(contract.itemPhasePrefix.slice(i + '<phase>'.length)));
}

/** Explicit `phase` field or valid `[<phase>] ` content prefix; undefined when neither. */
function resolvePhase(item: TodoItem, contract: Contract): PhaseId | undefined {
  const todoPhases: readonly string[] = contract.todoPhases;
  if (item.phase && todoPhases.includes(item.phase)) return item.phase;
  const m = prefixRegex(contract)?.exec(item.content);
  if (m && m[1] !== undefined && todoPhases.includes(m[1])) return m[1] as PhaseId;
  return undefined;
}

/**
 * Read and slice the board's todos. Keep non-archived items that are open
 * (status 'pending' or 'in_progress', any session: the backlog) or belong to
 * this session (so completed counts stay session-scoped). `phase` is stamped on every returned item from the field
 * or the content prefix. Missing or corrupt file => empty list, never throws.
 * Cache is reused verbatim (no re-filter, no re-read) while stat mtimeMs is
 * unchanged; it is only valid for the same root/session/memberNames context.
 */
export async function readTodos(
  fs: FsLike,
  root: string,
  sessionId: string,
  memberNames: string[],
  contract: Contract,
  cache?: TodosCache,
): Promise<{ items: TodoItem[]; cache: TodosCache }> {
  const path = `${root.replace(/\/+$/, '')}/.atlas/.run/todos.json`;
  const st = await fs.stat(path).catch(() => undefined);
  if (cache && cache.mtimeMs === (st ? st.mtimeMs : 0)) return { items: cache.items, cache };

  // stat undefined => file missing (FsLike read would throw); skip the read.
  const raw = st === undefined ? undefined : await fs.read(path).catch(() => undefined);
  let parsed: TodoItem[] = [];
  if (raw !== undefined) {
    try {
      const data = JSON.parse(raw) as { items?: unknown };
      if (Array.isArray(data?.items)) parsed = data.items as TodoItem[];
    } catch { // corrupt JSON => empty list
    }
  }
  // Unphased items stay unphased (grouped as 'unsorted'); never defaulted to a real phase.
  const items = parsed
    .filter(it => !it.archived)
    .filter(it => it.session_id === sessionId ||
      it.status === 'pending' || it.status === 'in_progress')
    .map(it => ({ ...it, phase: resolvePhase(it, contract) }));
  const next: TodosCache = { mtimeMs: st ? st.mtimeMs : 0, items };
  return { items, cache: next };
}

/** Board rows carry `origin` (session|carried|manual|advisor) at runtime; TodoItem (locked contract) does not declare it. */
type BoardItem = TodoItem & { origin?: string; created_at?: number | string };
const createdAt = (it: BoardItem): number => Number(it.created_at) || 0;
const isLive = (it: BoardItem, sessionId: string): boolean =>
  it.session_id === sessionId || (it.status !== 'completed' && it.origin !== 'carried');

/** Advisor notes are not operating-contract work: they never join phase groups or progress. */
const isAdvisor = (it: BoardItem): boolean => it.origin === 'advisor';
/** Carried rows are re-stamped with the new session id at boot (atlas_todo.carry) yet belong to an earlier plan. */
const notOwn = (it: BoardItem): boolean => it.origin === 'advisor' || it.origin === 'carried';
/** Session-origin (explicit, or legacy rows without origin owned by this session). */
const isSessionOrigin = (it: BoardItem, sessionId: string): boolean =>
  it.origin === 'session' || (it.origin === undefined && it.session_id === sessionId);

const clip = (s: string, n: number): string => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

/**
 * Contract groups (todoPhases order) hold only phased items or phase-less session-origin items ('unsorted');
 * open advisor notes form one final 'advisor' group (the pane keeps it collapsed). Live items first, empty groups dropped.
 */
export function groupTodos(items: TodoItem[], contract: Contract, sessionId: string): TodoGroup[] {
  const order: (PhaseId | 'unsorted')[] = [...contract.todoPhases, 'unsorted'];
  const rank: Record<string, number> = { in_progress: 0, pending: 1, completed: 2 };
  const row = (it: BoardItem) => ({
    id: it.id, content: clip(it.content, 160), status: it.status, owner: it.owner ?? null, evidence: it.evidence ? clip(it.evidence, 200) : null,
    live: isLive(it, sessionId),
  });
  const contractItems = items.filter(it => !notOwn(it));
  const groups: TodoGroup[] = [];
  for (const phase of order) {
    const mine = contractItems.filter(it => {
      const p = resolvePhase(it, contract);
      return p !== undefined ? p === phase : phase === 'unsorted' && isSessionOrigin(it, sessionId);
    });
    if (mine.length === 0) continue;
    const rows = mine
      .map(row)
      .sort((a, b) => Number(b.live) - Number(a.live) || (rank[a.status] ?? 1) - (rank[b.status] ?? 1));
    groups.push({
      phase,
      dept: phase === 'unsorted' ? 'UNSORTED' : (DEPT[phase] ?? phase.toUpperCase()),
      glyph: phase === 'unsorted' ? '·' : (contract.phases.find(p => p.id === phase)?.glyph ?? '·'),
      items: rows,
      done: rows.filter(r => r.status === 'completed').length,
      total: rows.length,
    });
  }
  // Newest first: the pane shows the two most recent and folds the older ones into "+N more".
  const advisors = items.filter(it => isAdvisor(it) && it.status !== 'completed')
    .sort((a, b) => createdAt(b) - createdAt(a)).map(row);
  if (advisors.length > 0) {
    groups.push({ phase: 'advisor', dept: 'ADVISOR NOTES', glyph: '·', items: advisors, done: 0, total: advisors.length });
  }
  return groups;
}

/** AtlasSnapshot['counts']: done/total overall and per contract.todoPhases phase. */
export function computeCounts(items: TodoItem[], contract: Contract): AtlasSnapshot['counts'] {
  const byPhase: Record<string, PhaseCount> = {};
  for (const p of contract.todoPhases) byPhase[p] = { done: 0, total: 0 };
  let done = 0;
  for (const it of items) {
    if (it.status === 'completed') done++;
    const phase = resolvePhase(it, contract);
    if (phase === undefined) continue; // unstamped, no valid prefix: totals only
    const c = byPhase[phase] ??= { done: 0, total: 0 };
    c.total++;
    if (it.status === 'completed') c.done++;
  }
  return { done, total: items.length, byPhase };
}

/** Current phase: header > first in_progress item's phase > 'research'. */
export function currentPhase(
  items: TodoItem[],
  headerPhase: PhaseId | null,
): { phase: PhaseId; source: 'header' | 'todo' | 'default' } {
  // The run's own active todo is the live phase; the reply header is the lead's claim for this turn only.
  const active = items.find(it => it.status === 'in_progress');
  if (active?.phase) return { phase: active.phase, source: 'todo' };
  if (headerPhase) return { phase: headerPhase, source: 'header' };
  return { phase: 'research', source: 'default' };
}

/** done/total over exactly the tasks the route shows: items of the contract-phase groups (advisor notes and unsorted excluded). */
export function routeCounts(groups: readonly TodoGroup[], contract: Contract): { done: number; total: number } {
  const phases: readonly string[] = contract.todoPhases;
  const items = groups.filter((g) => phases.includes(g.phase)).flatMap((g) => g.items);
  return { done: items.filter((i) => i.status === 'completed').length, total: items.length };
}

files.mod/data/channels.ts:
// Board + roster readers for the Atlas mod: pure logic over FsLike (register.ts adapts $.fs).
// Ported from plugins/atlas/omp/channel-view.ts (readChannelNotes/formatNote) — mods have no Node APIs,
// so paths join with '/' and parsing is defensive. Never shells out to atlas_todo.py.
import type { ChannelMember, ChannelNote, FsLike } from '../contract';

const MAX_NOTES = 500;
const MAX_LINE = 110;

const str = (v: unknown): string | undefined => (typeof v === 'string' ? v : undefined);

/** Board ts as a string the rest of the mod can rely on: ISO when parseable, '' when absent. */
function isoTs(ts: unknown): string {
	if (typeof ts === 'number' && Number.isFinite(ts)) {
		const ms = ts < 1e12 ? ts * 1000 : ts; // epoch seconds vs ms
		const d = new Date(ms);
		return Number.isNaN(d.getTime()) ? '' : d.toISOString();
	}
	if (typeof ts === 'string') {
		const ms = Date.parse(ts);
		return Number.isNaN(ms) ? ts : new Date(ms).toISOString();
	}
	return '';
}

/** One JSONL line -> ChannelNote of `channel`; undefined for blank/torn/malformed lines and other channels. */
function parseNote(raw: string, channel: string): ChannelNote | undefined {
	if (!raw.trim()) return undefined;
	let rec: unknown;
	try {
		rec = JSON.parse(raw);
	} catch {
		return undefined; // blank or torn line: skip it, keep the rest
	}
	if (!rec || typeof rec !== 'object') return undefined;
	const r = rec as Record<string, unknown>;
	if (r.channel !== channel) return undefined;
	const seq = Number(r.seq);
	return {
		ts: isoTs(r.ts),
		seq: Number.isFinite(seq) ? seq : 0,
		owner: typeof r.owner === 'string' ? r.owner : '',
		to: str(r.to),
		item: str(r.item),
		text: typeof r.text === 'string' ? r.text : '',
		channel,
		kind: str(r.kind),
	};
}


/**
 * Incremental reader over <root>/.atlas/.run/board/*.jsonl. Keeps a per-file byte cursor from stat.size:
 * a file is re-read (and re-parsed) only when its size grew or shrank; unchanged files reuse their notes.
 */
export class NoteReader {
	private cursors = new Map<string, number>();
	private parsed = new Map<string, ChannelNote[]>();

	constructor(private readonly fs: FsLike, private readonly root: string) {}

	/** All notes of `channel`, oldest first, capped at the last 500; [] when the board is missing/unreadable. */
	async read(channel: string): Promise<ChannelNote[]> {
		const dir = `${this.root}/.atlas/.run/board`;
		let files: string[];
		try {
			files = await this.fs.list(dir);
		} catch {
			return [];
		}
		const out: ChannelNote[] = [];
		for (const file of files) {
			if (!file.endsWith('.jsonl')) continue;
			const path = `${dir}/${file}`;
			let size: number | undefined;
			try {
				size = (await this.fs.stat(path))?.size;
			} catch {
				size = undefined;
			}
			if (size !== undefined && size === this.cursors.get(file)) {
				out.push(...(this.parsed.get(file) ?? []));
				continue;
			}
			// size grew, shrank, or first sight: re-read and re-parse the whole file
			let raw: string | undefined;
			try {
				raw = await this.fs.read(path);
			} catch {
				raw = undefined;
			}
			if (raw === undefined) {
				this.cursors.delete(file);
				this.parsed.delete(file);
				continue;
			}
			const notes: ChannelNote[] = [];
			for (const line of raw.split('\n')) {
				const note = parseNote(line, channel);
				if (note) notes.push(note);
			}
			// ponytail: whole-file reparse on any size change; tail-read from the cursor if boards grow past a few MB
			this.cursors.set(file, size ?? 0);
			this.parsed.set(file, notes);
			out.push(...notes);
		}
		// ISO strings compare lexicographically; '' (missing ts) sorts first, seq dominates anyway
		return out.sort((a, b) => a.seq - b.seq || (a.ts < b.ts ? -1 : a.ts > b.ts ? 1 : 0)).slice(-MAX_NOTES);
	}
}

/**
 * Roster for the first candidate channel present in <root>/.atlas/.run/channels.json
 * (`channels[name].members[]`); `{channel: null, members: []}` when nothing matches or the file is unreadable.
 */
export async function readRoster(
	fs: FsLike,
	root: string,
	candidates: string[],
): Promise<{ channel: string | null; members: ChannelMember[] }> {
	let reg: unknown;
	try {
		const raw = await fs.read(`${root}/.atlas/.run/channels.json`);
		reg = raw === undefined ? undefined : JSON.parse(raw);
	} catch {
		reg = undefined;
	}
	const channels = (reg as { channels?: Record<string, unknown> } | undefined)?.channels;
	if (!channels || typeof channels !== 'object') return { channel: null, members: [] };
	for (const name of candidates) {
		const members = (channels[name] as { members?: unknown } | undefined)?.members;
		if (!Array.isArray(members)) continue;
		return {
			channel: name,
			members: members.flatMap((m) => {
				if (!m || typeof m !== 'object') return [];
				const e = m as Record<string, unknown>;
				if (typeof e.name !== 'string') return [];
				return [
					{
						name: e.name,
						...(e.role !== undefined ? { role: str(e.role) } : {}),
						...(e.pane_id !== undefined ? { pane_id: str(e.pane_id) } : {}),
						...(typeof e.pid === 'number' ? { pid: e.pid } : {}),
						...(e.ended_at !== undefined ? { ended_at: str(e.ended_at) ?? null } : {}),
						...(typeof e.exit_code === 'number' ? { exit_code: e.exit_code } : {}),
					},
				];
			}),
		};
	}
	return { channel: null, members: [] };
}

/** `HH:MM owner → to │ text`, whitespace collapsed, cut to 110; HH:MM from `n.ts`, falling back to `now`. */
export function formatNote(n: ChannelNote, now: number): string {
	const d = new Date(Date.parse(n.ts));
	const t = Number.isNaN(d.getTime()) ? new Date(now) : d;
	const hhmm = `${String(t.getHours()).padStart(2, '0')}:${String(t.getMinutes()).padStart(2, '0')}`;
	const line = `${hhmm} ${n.owner || '?'} → ${n.to || 'all'} │ ${(n.text ?? '').replace(/\s+/g, ' ').trim()}`;
	return line.length > MAX_LINE ? `${line.slice(0, MAX_LINE - 1)}…` : line;
}

/** The departure line for a `kind: 'exit'` note; undefined for every other kind. */
export function systemLine(n: ChannelNote): string | undefined {
	if (n.kind !== 'exit') return undefined;
	const code = n.text.match(/\bexit (\d+)\b/)?.[1] ?? String(n.seq);
	return `*** ${n.owner || '?'} has quit (exit ${code})`;
}

files.mod/data/personas.ts:
// Persona frontmatter parsing + loaders, colour tables and the task-routing matrix.
// Data sources: <pluginRoot>/agents/*.md and <pluginRoot>/contracts/operating-contract.json.
// Loaders are pure over FsLike (see contract.ts) so register.ts can adapt $.fs and the
// test kit can drive them from memory. No Node imports: mod modules run sandboxed.
import type { Contract, FsLike, Persona, PhaseId } from '../contract';
import { BRAND } from '../contract';
import { contractGlyph } from '../theme';

/** Frontmatter colour name -> hex, mirroring the dashboard token palette (dashboard_ui/css/tokens.css). */
export const PERSONA_COLORS: Record<string, string> = {
  green: BRAND.ok, // #52c872
  red: BRAND.fail, // #ff7570
  blue: BRAND.working, // #62b8e6
  cyan: '#56d4dd',
  yellow: BRAND.input, // #f2aa40
  pink: '#f472b6',
  purple: BRAND.subagent, // #b5a3fa
  orange: '#f2994a',
  teal: BRAND.accent, // #2fbd9f
};

/**
 * Persona name (or 'atlas:'-prefixed token) -> frontmatter colour name, mirrored
 * from plugins/atlas/agents/*.md so UI panes can colour by name without loading
 * the files. Frontmatter stays the source of truth for model/effort.
 */
const PERSONA_BY_NAME: Record<string, string> = {
  'completeness-critic': 'red',
  'db-prober': 'yellow',
  'docs-auditor': 'orange',
  'docs-curator': 'purple',
  explorer: 'cyan',
  implementer: 'green',
  'naming-glossary-audit': 'orange',
  planner: 'blue',
  'rls-privilege-audit': 'orange',
  runner: 'orange',
  'schema-inventory': 'cyan',
  'ui-runtime-tester': 'pink',
  verifier: 'red',
};

/**
 * Resolve an identity token to a '#rrggbb' hex.
 * Accepts a persona name ('implementer', 'atlas:implementer'), a frontmatter
 * colour name (Persona.color), or a squad token (SquadAgent.persona):
 * 'armada-<dept>' wears the subagent token, anything unrecognised (incl.
 * 'unknown') goes idle.
 */
export function personaColor(persona: string): string {
  if (persona.startsWith('armada-')) return BRAND.subagent;
  const key = persona.toLowerCase().replace(/^atlas:/, '');
  const mapped = PERSONA_BY_NAME[key];
  return PERSONA_COLORS[key] ?? (mapped === undefined ? undefined : PERSONA_COLORS[mapped]) ?? BRAND.idle;
}

/**
 * Parse the simple YAML head of an agent file: `key: value` lines between the
 * opening `---` fence and the closing one. Splits on the first `:` (descriptions
 * contain colons), strips one pair of matching quotes, ignores anything else.
 */
export function parseFrontmatter(md: string): Record<string, string> {
  const out: Record<string, string> = {};
  if (!md.startsWith('---')) return out;
  for (const raw of md.slice(3).split(/\r?\n/)) {
    const line = raw.trim();
    if (line === '---') break; // closing fence
    if (line === '') continue;
    const colon = line.indexOf(':');
    if (colon <= 0) break; // non `key: value` line ends the simple head
    let value = line.slice(colon + 1).trim();
    if (value.length >= 2 && ((value[0] === '"' && value.endsWith('"')) || (value[0] === "'" && value.endsWith("'")))) {
      value = value.slice(1, -1);
    }
    out[line.slice(0, colon).trim()] = value;
  }
  return out;
}

/** Load every persona from <pluginRoot>/agents/*.md, in stable file order. */
export async function loadPersonas(fs: FsLike, pluginRoot: string): Promise<Persona[]> {
  const dir = `${pluginRoot}/agents`;
  const entries = (await fs.list(dir)).filter((n) => n.endsWith('.md')).sort();
  const personas: Persona[] = [];
  for (const entry of entries) {
    const path = entry.includes('/') ? entry : `${dir}/${entry}`;
    const md = await fs.read(path);
    if (md === undefined) continue;
    const fm = parseFrontmatter(md);
    if (!fm.name) continue;
    personas.push({
      name: fm.name,
      model: fm.model || 'inherit',
      effort: fm.effort || 'low',
      color: fm.color || 'unknown',
      description: fm.description || '',
    });
  }
  return personas;
}

/** Load the operating contract from <pluginRoot>/contracts/operating-contract.json. */
export async function loadContract(fs: FsLike, pluginRoot: string): Promise<Contract> {
  const path = `${pluginRoot}/contracts/operating-contract.json`;
  const raw = await fs.read(path);
  if (raw === undefined) throw new Error(`operating contract not found: ${path}`);
  let json: {
    phases?: { id?: string; glyph?: string }[];
    todoPhases?: string[];
    headerFirstLinePattern?: string;
    itemPhasePrefix?: string;
  };
  try {
    json = JSON.parse(raw);
  } catch (err) {
    throw new Error(`operating contract is not valid JSON: ${path} (${err instanceof Error ? err.message : String(err)})`);
  }
  return {
    phases: (json.phases ?? []).map((p) => ({ id: (p.id ?? 'research') as PhaseId, glyph: contractGlyph(p.glyph ?? '') })),
    todoPhases: (json.todoPhases ?? []) as PhaseId[],
    headerFirstLinePattern: json.headerFirstLinePattern ?? '',
    itemPhasePrefix: json.itemPhasePrefix ?? '[<phase>] ',
  };
}

export interface RoutingRow {
  task: string;
  persona: string; // single persona token; the display row 'DB catalog dump; naming audit' combines two with '; '
  model: string;
  effort: string;
}

/** Task-type routing, copied verbatim from the plan (docs/plans/2026-10-09-atlas-mod.md section 5). Claude-side values. */
export const ROUTING_MATRIX: RoutingRow[] = [
